// List of public pages to crawl (edit freely) + crawl state from the previous run.
// ---- shared LLM helper (inlined into Code nodes by build_workflows.py) ----
// LLM_PROVIDER=gemini (hosted, rate-limited free tier) | ollama (local open model, unlimited, no key)
const LLM_PROVIDER = String($env.LLM_PROVIDER || 'gemini').toLowerCase();
function llmConfigError() {
  if (LLM_PROVIDER === 'gemini' && !$env.GEMINI_API_KEY) return 'LLM_PROVIDER=gemini but GEMINI_API_KEY is not set';
  if (LLM_PROVIDER !== 'gemini' && LLM_PROVIDER !== 'ollama') return `unknown LLM_PROVIDER "${LLM_PROVIDER}"`;
  return null;
}
// Returns the model's answer parsed as JSON. Retries transient failures with backoff.
async function callLLM(ctx, prompt) {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      let text;
      if (LLM_PROVIDER === 'ollama') {
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', url: `${$env.OLLAMA_URL || 'http://ollama:11434'}/api/chat`, json: true, timeout: 300000,
          body: { model: $env.OLLAMA_MODEL || 'qwen2.5:3b', stream: false, format: 'json',
                  options: { temperature: 0 }, messages: [{ role: 'user', content: prompt }] },
        });
        text = resp.message.content;
      } else {
        const model = $env.GEMINI_MODEL || 'gemini-3.5-flash-lite';
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', json: true, timeout: 90000,
          url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
          headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
          body: { contents: [{ parts: [{ text: prompt }] }],
                  generationConfig: { responseMimeType: 'application/json', temperature: 0 } },
        });
        text = resp.candidates[0].content.parts.find((p) => typeof p.text === 'string').text;
      }
      return JSON.parse(text);
    } catch (e) {
      lastError = e;
      if (attempt < 3) await new Promise((r) => setTimeout(r, 2000 * attempt));
    }
  }
  throw lastError;
}
// ---- end shared helper ----

if (llmConfigError()) {
  throw new Error(`${llmConfigError()}. The crawler needs an LLM to extract products; seeded products stay active.`);
}
const state = {};
for (const r of $('Load Crawl State').all()) if (r.json.source) state[r.json.source] = r.json.content_hash;
const SOURCES = [
  { source: 'bankbazaar', url: 'https://www.bankbazaar.com/personal-loan.html' },
  { source: 'hdfcbank', url: 'https://www.hdfcbank.com/personal/borrow/popular-loans/personal-loan' },
];
return SOURCES.map((s) => ({ json: { ...s, previous_hash: state[s.source] || null } }));

// Strip a fetched page down to readable text, hash it, and flag whether it changed since last crawl.
const crypto = require('crypto');
const MAX_CHARS = 60000;
const sources = $('Sources').all();
return $input.all().map((item, i) => {
  const meta = sources[i].json;
  const html = typeof item.json.data === 'string' ? item.json.data : '';
  if (item.json.error || !html) {
    return { json: { source: meta.source, ok: false, changed: false, reason: String(item.json.error?.message || item.json.error || 'empty response') } };
  }
  const text = html
    .replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim().slice(0, MAX_CHARS);
  const hash = crypto.createHash('sha256').update(text).digest('hex');
  return { json: { source: meta.source, url: meta.url, ok: text.length > 500, changed: hash !== meta.previous_hash, content_hash: hash, text } };
});

// Ask the LLM to extract products from the page text, then validate before anything is written.
// ---- shared LLM helper (inlined into Code nodes by build_workflows.py) ----
// LLM_PROVIDER=gemini (hosted, rate-limited free tier) | ollama (local open model, unlimited, no key)
const LLM_PROVIDER = String($env.LLM_PROVIDER || 'gemini').toLowerCase();
function llmConfigError() {
  if (LLM_PROVIDER === 'gemini' && !$env.GEMINI_API_KEY) return 'LLM_PROVIDER=gemini but GEMINI_API_KEY is not set';
  if (LLM_PROVIDER !== 'gemini' && LLM_PROVIDER !== 'ollama') return `unknown LLM_PROVIDER "${LLM_PROVIDER}"`;
  return null;
}
// Returns the model's answer parsed as JSON. Retries transient failures with backoff.
async function callLLM(ctx, prompt) {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      let text;
      if (LLM_PROVIDER === 'ollama') {
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', url: `${$env.OLLAMA_URL || 'http://ollama:11434'}/api/chat`, json: true, timeout: 300000,
          body: { model: $env.OLLAMA_MODEL || 'qwen2.5:3b', stream: false, format: 'json',
                  options: { temperature: 0 }, messages: [{ role: 'user', content: prompt }] },
        });
        text = resp.message.content;
      } else {
        const model = $env.GEMINI_MODEL || 'gemini-3.5-flash-lite';
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', json: true, timeout: 90000,
          url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
          headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
          body: { contents: [{ parts: [{ text: prompt }] }],
                  generationConfig: { responseMimeType: 'application/json', temperature: 0 } },
        });
        text = resp.candidates[0].content.parts.find((p) => typeof p.text === 'string').text;
      }
      return JSON.parse(text);
    } catch (e) {
      lastError = e;
      if (attempt < 3) await new Promise((r) => setTimeout(r, 2000 * attempt));
    }
  }
  throw lastError;
}
// ---- end shared helper ----

const EMPLOYMENT = ['Salaried', 'Self-Employed', 'Business'];
const num = (v) => (typeof v === 'number' && isFinite(v) && v >= 0 ? v : null);
const PROMPT =
  'You extract personal loan products from a lender web page. Respond with a single JSON object ' +
  '{"products": [...]}. Each product: {product_name, interest_rate (lowest annual % as a number or null), ' +
  'min_income (minimum MONTHLY income as a number or null), min_credit_score, max_credit_score, min_age, max_age, ' +
  'allowed_employment (array of "Salaried", "Self-Employed", "Business" or null), criteria_text (the page\'s ' +
  'eligibility wording for this product, verbatim, or null)}. Only include personal loan products actually ' +
  'described on the page. Use null for anything not stated. Do not invent values.\n\nPAGE TEXT:\n';

const meta = $json;
let raw = [];
let error = null;
try {
  const parsed = await callLLM(this, PROMPT + meta.text);
  raw = Array.isArray(parsed) ? parsed : (parsed.products || []);
} catch (e) {
  error = e.message; // nothing is written and the hash is not stored, so the next run retries
}

const products = [];
for (const p of raw) {
  if (!p || typeof p.product_name !== 'string' || !p.product_name.trim()) continue;
  const allowed = Array.isArray(p.allowed_employment) ? p.allowed_employment.filter((e) => EMPLOYMENT.includes(e)) : [];
  const row = {
    product_name: p.product_name.trim().slice(0, 200),
    interest_rate: num(p.interest_rate),
    min_income: num(p.min_income), min_credit_score: num(p.min_credit_score), max_credit_score: num(p.max_credit_score),
    min_age: num(p.min_age), max_age: num(p.max_age),
    allowed_employment: allowed.length ? allowed : null,
    criteria_text: typeof p.criteria_text === 'string' && p.criteria_text.trim() ? p.criteria_text.trim().slice(0, 2000) : null,
  };
  if (row.min_income == null && row.min_credit_score == null && !row.criteria_text) continue; // no criteria at all
  products.push(row);
}
return { json: { source: meta.source, content_hash: meta.content_hash, products, error } };
